def merge_mobile_duplicates(apps, schema_editor):
    Customer = apps.get_model('billing', 'Customer')
    Invoice = apps.get_model('billing', 'Invoice')
    seen = {}
    for customer in Customer.objects.order_by('business_id', 'pk').iterator():
        digits = re.sub(r'[\s()+-]', '', customer.mobile)
        if len(digits) == 10: digits = '91' + digits
        normalized = '+' + digits if re.fullmatch(r'91[6-9]\d{9}', digits) else customer.mobile
        key = (customer.business_id, normalized)
        canonical = seen.get(key)
        if canonical:
            # Preserve the complete old customer row and all immutable invoice snapshots.
            Customer.objects.filter(pk=customer.pk).update(merged_into_id=canonical, mobile=normalized)
            Invoice.objects.filter(customer_id=customer.pk).update(customer_id=canonical)
        else:
            seen[key] = customer.pk
            Customer.objects.filter(pk=customer.pk).update(mobile=normalized)


